        .FeatureGrid_main{
        position:relative;
        width:100%;
        padding:100px 24px 120px;
        background-color:#000;
        overflow:hidden;
        display:flex;
        flex-direction:column;
        align-items:center;
        }
        
        /* soft violet corner glow, top-left — matches the "What You'll Learn" screenshot */
        .FeatureGrid_glow{
        position:absolute;
        top:-100px;
        left:-150px;
        width:600px;
        height:600px;
        background:radial-gradient(circle, rgba(168,85,247,.35) 0%, rgba(168,85,247,0) 70%);
        pointer-events:none;
        z-index:0;
        }
        
        .FeatureGrid_title{
        position:relative;
        z-index:1;
        font-family:Gilroy-Extra-Bold,sans-serif;
        font-size:52px;
        text-align:center;
        margin:0 0 24px;
        }
        
        .FeatureGrid_title_purple{
        background:linear-gradient(90deg,#A855F7,#7C3AED);
        -webkit-background-clip:text;
        background-clip:text;
        -webkit-text-fill-color:transparent;
        }
        
        .FeatureGrid_title_white{
        color:#ffffff;
        }
        
        .FeatureGrid_subtitle{
        position:relative;
        z-index:1;
        font-family:Gilroy-Regular,sans-serif;
        font-size:18px;
        line-height:1.6;
        color:#d0d0d0;
        text-align:center;
        max-width:800px;
        margin:0 0 56px;
        }
        
        .FeatureGrid_grid{
        position:relative;
        z-index:1;
        display:grid;
        grid-template-columns:repeat(3,1fr);
        gap:24px;
        width:100%;
        max-width:1300px;
        }
        
        .FeatureGrid_card{
        background:linear-gradient(180deg,#1a0f2e,#0a0612);
        border:1px solid rgba(168,85,247,.3);
        border-radius:16px;
        padding:32px 28px;
        display:flex;
        flex-direction:column;
        align-items:center;
        text-align:center;
        transition:border-color .2s ease;
        }
        
        .FeatureGrid_card:hover{
        border-color:rgba(168,85,247,.7);
        }
        
        .FeatureGrid_icon_circle{
        width:64px;
        height:64px;
        border-radius:50%;
        display:flex;
        align-items:center;
        justify-content:center;
        margin-bottom:20px;
        background:#0a0612;
        border:1.5px solid;
        border-image:linear-gradient(135deg,#D946EF,#7C3AED) 1;
        }
        
        .FeatureGrid_icon{
        width:26px;
        height:26px;
        color:#fff;
        }
        
        .FeatureGrid_card_title{
        font-family:Gilroy-Bold,sans-serif;
        font-size:19px;
        color:#fff;
        margin:0 0 8px;
        }
        
        .FeatureGrid_card_desc{
        font-family:Gilroy-Regular,sans-serif;
        font-size:14px;
        color:#9a9a9a;
        margin:0;
        }
        
        @media (max-width:900px){
        .FeatureGrid_title{ font-size:34px; }
        .FeatureGrid_subtitle{ font-size:15px; }
        .FeatureGrid_grid{ grid-template-columns:1fr; }
        }


    </style>
    

