.Speakers_speakers_cntnr__xtiKH {
    display: grid !important;
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 24px !important;
    padding: 20px !important;
    width: 100% !important;
}

@media (max-width: 1024px) {
    .Speakers_speakers_cntnr__xtiKH {
        grid-template-columns: repeat(2, 1fr) !important;
    }
}

