    .Speakers_speakers_cntnr__xtiKH {
        grid-template-columns: 1fr !important;
    }
}

.tq-speaker-card {
    background: linear-gradient(160deg, #14141a 0%, #0b0b0f 100%) !important;
    border: 1px solid rgba(247, 211, 138, 0.18) !important;
    border-radius: 16px !important;
    overflow: hidden !important;
    transition: transform 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease !important;
    width: 100% !important;
}

.tq-speaker-card:hover {
    transform: translateY(-6px) !important;
    border-color: rgba(247, 211, 138, 0.55) !important;
    box-shadow: 0 12px 30px rgba(247, 211, 138, 0.08) !important;
}

.tq-speaker-img {
    position: relative !important;
    width: 100% !important;
    aspect-ratio: 1 / 1 !important;
    overflow: hidden !important;
    background: #1b1b22 !important;
}

.tq-speaker-img img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block !important;
    filter: grayscale(15%) !important;
    transition: filter 0.3s ease, transform 0.4s ease !important;
}

.tq-speaker-card:hover .tq-speaker-img img {
    filter: grayscale(0%) !important;
    transform: scale(1.05) !important;
}

.tq-speaker-tag {
    position: absolute !important;
    top: 12px !important;
    left: 12px !important;
    background: rgba(0, 0, 0, 0.55) !important;
