<script>
    (function(){
    // Change this to your real event date/time if different.
    var target = new Date("2026-08-14T14:00:00+05:30").getTime();
    
    function tick(){
        var now = new Date().getTime();
        var diff = target - now;
        if (diff < 0) diff = 0;
    
        var days = Math.floor(diff / (1000*60*60*24));
        var hours = Math.floor((diff % (1000*60*60*24)) / (1000*60*60));
        var mins = Math.floor((diff % (1000*60*60)) / (1000*60));
    
        document.getElementById("cd-days").textContent = String(days).padStart(2,"0");
        document.getElementById("cd-hours").textContent = String(hours).padStart(2,"0");
        document.getElementById("cd-mins").textContent = String(mins).padStart(2,"0");
    }
    tick();
    setInterval(tick, 1000 * 30); // refresh every 30s, no need for per-second churn on a minutes-level display
    })();
</script>
<script>
(function () {
    var btn = document.getElementById('eo-show-more-btn');
    var panel = document.getElementById('eo-more-desc');
    if (btn && panel) {
        btn.addEventListener('click', function () {
            var isHidden = panel.style.display === 'none';
            panel.style.setProperty('display', isHidden ? 'block' : 'none', 'important');
            btn.textContent = isHidden ? 'Show Less' : 'Show More';
        });
    }
})();
</script>
</html>
